UPDATE purchase_order_detail
SET product_id = #{productId}, product_code = #{productCode}, product_name = #{productName},
    batch_no = #{batchNo}, unit_id = #{unitId}, unit_name = #{unitName},
    price = #{price}, quantity = #{quantity}, amount = #{amount},
    delivered_qty = #{deliveredQty}, received_qty = #{receivedQty}, remark = #{remark}
WHERE id = #{id}
